import {automaticPoints,validateQuestionExtras,blankIds} from './question-types.js';
export function safeLink(value){if(!value)return '';const u=new URL(value);if(u.protocol!=='https:'||u.username||u.password)throw Error('Use um link HTTPS sem senha.');return u.href;}
export function validateExam(e){if(!e.title?.trim()||!Array.isArray(e.questions)||!e.questions.length||e.questions.length>100)throw Error('Informe título e de 1 a 100 questões.');if(!['grade','concept'].includes(e.grading))throw Error('Escolha nota ou conceito.');if(!Number.isFinite(e.scale)||e.scale<=0||e.scale>100)throw Error('Escala inválida.');const ids=new Set();for(const q of e.questions){if(!q.id||ids.has(q.id)||!/^[\w-]+$/.test(q.id))throw Error('IDs de questões devem ser únicos.');ids.add(q.id);if(!q.prompt?.trim()||!['choice','multiple','open','blanks'].includes(q.type)||!Number.isFinite(q.points)||q.points<=0||!validateQuestionExtras(q))throw Error('Questão inválida: '+q.id);if(q.type==='choice'&&(!Array.isArray(q.options)||q.options.length<2||q.options.length>6||q.options.some(o=>typeof o!=='string'||!o.trim())||!Number.isInteger(q.correct)||q.correct<0||q.correct>=q.options.length))throw Error('Alternativas/gabarito inválidos: '+q.id);}return e;}
export function splitExam(exam){validateExam(exam);const keys={};const questions=exam.questions.map(q=>{keys[q.id]=structuredClone(q);const {correct,corrects,blanks,rubric,...pub}=q;if(blanks)pub.blankCount=blanks.length;return pub;});return {questions,keys};}
export function gradeAttempt(exam,keys,answers,manual={}){let earned=0,total=0;const feedback={};for(const pub of exam.questions){const q=keys[pub.id];if(!q)throw Error('Gabarito não encontrado.');let points;if(q.type==='open'){const m=manual[q.id];if(!m||!Number.isFinite(Number(m.points))||Number(m.points)<0||Number(m.points)>q.points)throw Error('Corrija a questão '+q.id);points=Number(m.points);}else points=automaticPoints(q,answers[q.id]);earned+=points;total+=q.points;feedback[q.id]={points,feedback:String(manual[q.id]?.feedback||'')};}const percent=earned/total*100;return {earned,total,percent,grade:Math.round(percent/100*exam.scale*100)/100,concept:percent>=99.999?'A':percent>=70?'B':percent>=40?'C':'D',feedback};}
export function risk(results){return results.filter(r=>r.grading==='concept'&&r.concept==='D').length>=2||results.some(r=>r.grading==='grade'&&r.grade/r.scale*100<70);}
export function publicAnswers(q,root){if(q.type==='choice'){const el=root.querySelector('input:checked');if(!el)throw Error('Responda '+q.id);return Number(el.value);}if(q.type==='multiple')return [...root.querySelectorAll('input:checked')].map(x=>Number(x.value));if(q.type==='blanks'){const a=[...root.querySelectorAll('input')].map(x=>x.value.trim());if(a.some(x=>!x))throw Error('Preencha as lacunas de '+q.id);return a;}const s=root.querySelector('textarea').value;if(!s.trim())throw Error('Responda '+q.id);return s;}
export function validateBackup(b){if(b?.format!=='conexoes-spark-1'||!Array.isArray(b.docs)||b.docs.length>20000)throw Error('Backup incompatível.');const seen=new Set();for(const x of b.docs){if(typeof x.path!=='string'||!/^spark(Profiles|RegistrationDecisions|Plans|PlanPayments|Courses|Invites|Leads|Bank|Institutions)(\/[^/]+)+$/.test(x.path)||x.path.split('/').length%2||seen.has(x.path)||!x.data||typeof x.data!=='object'||Array.isArray(x.data)||JSON.stringify(x.data).length>700000||x.path.split('/').some(s=>['__proto__','constructor','prototype'].includes(s)))throw Error('Caminho/dados inválidos no backup.');seen.add(x.path);}return b;}
export const SAMPLE={title:'Redes de computadores',subject:'Redes',date:'',grading:'concept',scale:100,questions:[{id:'q1',type:'choice',points:2,prompt:'Half-duplex permite envio e recebimento simultâneos?',options:['Sim','Não','Não sei'],correct:1},{id:'q2',type:'multiple',points:3,prompt:'Selecione as afirmações corretas.',options:['Switch aprende pelo MAC de origem.','ARP associa IPv4 e MAC na rede local.','Hub consulta tabela MAC.'],corrects:[0,1]},{id:'q3',type:'blanks',points:2,prompt:'No {{1}}, enviar e receber podem ocorrer ao mesmo tempo.',ignoreCase:true,ignoreAccents:true,blanks:[{accepted:['full-duplex','full duplex']}]},{id:'q4',type:'open',points:3,prompt:'Explique a diferença entre hub e switch.',responseFormat:'text'}]};
